sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    const PROPERTY_NAME = "x_110383_home_me_0.snow_fall.ngrok_url";
    try {
		gs.info("Test" + JSON.stringify(request.body.data));
        const payload = request.body.data;

        gs.setProperty(PROPERTY_NAME, payload.url, "NGROK Public URL");

		response.setStatus(200);
		response.setContentType('application/json');
		response.setBody({"Message": "Success", PROPERTY_NAME: gs.getProperty(PROPERTY_NAME)});

    } catch (err) {
		response.setStatus(400);
		response.setContentType('application/json');
		response.setBody({"Error message": err.message, "Trace": err.stack, "Request": JSON.stringify(request)});
        gs.error(`Error while setting the property value\n${err.message}\nTrace\n${err.stack}`);
    }
	return;


})(request, response);
